body:
I'm using Babel 6, Webpack 2.
This wasn't an issue with v2.1.0-beta.8, but since I upgraded to v2.1.0-beta.12, I assume the problem is this commit:
https://github.com/webpack/webpack/commit/0bd5d281e297a615ed688cabe55e82a592fc20db
to hoist harmony exports.
(I could be totally wrong here - I'm not sure exactly how it works, just guessing it is putting harmony exports up near the top of chunks) 

It could be something else between those two releases though!

Here's an example from rxjs-es 5.0.0-beta.7 (though it could affect other rxjs versions):
File is rxjs-es/util/assign.js

```
import { root } from './root';
const Object = root.Object;
if (typeof Object.assign != 'function') {
    (function () {
        Object.assign = function assignPolyfill(target, ...sources) {
            if (target === undefined || target === null) {
                throw new TypeError('Cannot convert undefined or null to object');
            }
            const output = Object(target);
            const len = sources.length;
            for (let index = 0; index < len; index++) {
                let source = sources[index];
                if (source !== undefined && source !== null) {
                    for (let key in source) {
                        if (source.hasOwnProperty(key)) {
                            output[key] = source[key];
                        }
                    }
                }
            }
            return output;
        };
    })();
}
export const assign = Object.assign;
//# sourceMappingURL=assign.js.map
```

which is transformed into:

```
/* 346 */
/***/ function(module, exports, __webpack_require__) {

    "use strict";
    /* harmony import */ var __WEBPACK_IMPORTED_MODULE_0__root__ = __webpack_require__(9);

    /* harmony export */ Object.defineProperty(exports, "a", {configurable: false, enumerable: true, get: function() { return assign; }});
    var Object = __WEBPACK_IMPORTED_MODULE_0__root__["a" /* root */].Object;
    if (typeof Object.assign != 'function') {
        (function () {
            Object.assign = function assignPolyfill(target) {
                if (target === undefined || target === null) {
                    throw new TypeError('Cannot convert undefined or null to object');
                }
                var output = Object(target);

                for (var _len = arguments.length, sources = Array(_len > 1 ? _len - 1 : 0), _key = 1; _key < _len; _key++) {
                    sources[_key - 1] = arguments[_key];
                }

                var len = sources.length;
                for (var index = 0; index < len; index++) {
                    var source = sources[index];
                    if (source !== undefined && source !== null) {
                        for (var key in source) {
                            if (source.hasOwnProperty(key)) {
                                output[key] = source[key];
                            }
                        }
                    }
                }
                return output;
            };
        })();
    }
    var assign = Object.assign;
    //# sourceMappingURL=assign.js.map

/***/ },
```

because the const is turned into var and vars hoist (this I believe would also be a problem with const, potentially causing some kind of temporal dead zone issue), and the harmony export is put above that,

```
    /* harmony export */ Object.defineProperty(exports, "a", {configurable: false, enumerable: true, get: function() { return assign; }});
    var Object = __WEBPACK_IMPORTED_MODULE_0__root__["a" /* root */].Object;
```

is interpreted as

```
       var Object = undefined;
    /* harmony export */ Object.defineProperty(exports, "a", {configurable: false, enumerable: true, get: function() { return assign; }});
       Object = __WEBPACK_IMPORTED_MODULE_0__root__["a" /* root */].Object;
```

which throws
`Uncaught TypeError: Cannot read property 'defineProperty' of undefined`

Oops! This was working with v2.1.0-beta.8, I don't know the rationale of hoisting harmony exports - maybe we can isolate the effect of hoisting them, or is the nature of JS going to make this always potentially unsafe?

My dev dependencies are:

```
    "babel-loader": "^6.2.4",
    "babel-plugin-syntax-trailing-function-commas": "^6.8.0",
    "babel-plugin-transform-decorators": "^6.8.0",
    "babel-plugin-transform-function-bind": "^6.8.0",
    "babel-plugin-transform-node-env-inline": "^6.8.0",
    "babel-plugin-transform-object-rest-spread": "^6.8.0",
    "babel-plugin-transform-react-constant-elements": "^6.8.0",
    "babel-plugin-transform-react-inline-elements": "^6.8.0",
    "babel-preset-es2015": "^6.6.0",
    "babel-preset-es2015-webpack": "^6.4.0",
    "babel-preset-react": "^6.5.0",
    "webpack": "^2.1.0-beta.8"
```

I'm using the Webpack DedupePlugin and UglifyJSPlugin.

I get exactly the same problem when I turn off the babel transforms (function-bind, object-rest-spread, decorators, node-env-inline, syntax-trailing-function-commas, transform-react-constant-elements and transform-react-inline-elements) and the Webpack plugins listed above.

Using Webpack v2.1.0-beta.11 also gave me the same problem.

Please let me know if I can provide any more information about my build set up.
